			if ( ! $url ) { continue; }
			$parts[] = '<a href="' . esc_url( $url ) . '" style="color:' . self::C_ACCENT . ';">' . esc_html( $label ) . '</a>';
		}
		if ( ! $parts ) { return ''; }
		return '<tr><td style="font-size:14px;line-height:1.6;padding-bottom:20px;">' . implode( ' · ', $parts ) . '</td></tr>';
	}

